static int p2d89_emit_triangles_variants(P2D89_ShapeId id,const P2D89_Provider *p){static const p2d89_q14 eq[]={0,-16384,14189,8192,-14189,8192};static const p2d89_q14 iso[]={0,-16384,16384,12288,-16384,12288};static const p2d89_q14 scalene[]={-14336,12288,4096,-16384,16384,12288};static const p2d89_q14 rightt[]={-16384,-16384,-16384,16384,16384,16384};static const p2d89_q14 acute[]={0,-16384,12288,12288,-12288,12288};static const p2d89_q14 obtuse[]={-16384,10240,-8192,-12288,16384,10240};static const p2d89_q14 flat[]={-16384,8192,0,-4096,16384,8192};static const p2d89_q14 wedge[]={-16384,-12288,16384,0,-16384,12288};p2d89_u16 turn;if(id==P2D89_SHAPE_TRIANGLE_EQUILATERAL)return p2d89_i_poly(eq,3U,1,p);if(id==P2D89_SHAPE_TRIANGLE_SCALENE)return p2d89_i_poly(scalene,3U,1,p);if(id==P2D89_SHAPE_TRIANGLE_RIGHT)return p2d89_i_poly(rightt,3U,1,p);if(id==P2D89_SHAPE_TRIANGLE_ACUTE)return p2d89_i_poly(acute,3U,1,p);if(id==P2D89_SHAPE_TRIANGLE_OBTUSE)return p2d89_i_poly(obtuse,3U,1,p);if(id==P2D89_SHAPE_TRIANGLE_FLAT)return p2d89_i_poly(flat,3U,1,p);if(id==P2D89_SHAPE_TRIANGLE_WEDGE_LEFT)return p2d89_i_poly(wedge,3U,1,p);if(id==P2D89_SHAPE_TRIANGLE_WEDGE_RIGHT)return p2d89_i_rot_poly(wedge,3U,32768U,1,p);turn=0U;if(id==P2D89_SHAPE_TRIANGLE_ISOSCELES_DOWN)turn=32768U;else if(id==P2D89_SHAPE_TRIANGLE_ISOSCELES_LEFT)turn=49152U;else if(id==P2D89_SHAPE_TRIANGLE_ISOSCELES_RIGHT)turn=16384U;else if(id!=P2D89_SHAPE_TRIANGLE_ISOSCELES)return 0;return p2d89_i_rot_poly(iso,3U,turn,1,p);}
